delete_file.raw:
{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "Workspace-relative regular file, or directory/symlink with recursive:true."},
    "expected_sha256": {"type": "string", "description": "Optional regular-file SHA-256; omit to use the last observed version. Not accepted for directories or symlinks."},
    "recursive": {"type": "boolean", "description": "Explicitly authorize a directory tree or symlink deletion; default false."}
  },
  "required": ["path"],
  "additionalProperties": false
}

edit_file.raw:
{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "Workspace-relative UTF-8 text file to change."},
    "expected_sha256": {"type": "string", "description": "Optional. Omit it to use the version you last read or wrote; pass a digest only to name a specific version."},
    "old_text": {"type": "string", "description": "Single edit: exact text occurring once in the file."},
    "new_text": {"type": "string", "description": "Single edit: replacement text; empty deletes."},
    "edits": {"type": "array", "description": "Several non-overlapping replacements in one call.", "minItems": 1, "items": {
      "type": "object", "properties": {
        "old_text": {"type": "string"}, "new_text": {"type": "string"}, "replace_all": {"type": "boolean", "description": "Replace every non-overlapping occurrence of old_text."}
      }, "required": ["old_text", "new_text"], "additionalProperties": false
    }},
    "append_text": {"type": "string", "description": "Text added after all replacements; no automatic newline."}
  },
  "required": ["path"],
  "additionalProperties": false
}

exec.raw:
{
  "type": "object",
  "properties": {
    "argv": {"type": "array", "items": {"type": "string"}, "minItems": 1,
             "description": "The first or only command: its executable followed by its literal arguments, such as [\"git\",\"status\"]. Always an array, also when then is given."},
    "then": {"type": "array", "maxItems": 7,
             "items": {"type": "array", "items": {"type": "string"}, "minItems": 1},
             "description": "Commands to run after argv, each an argument vector like argv, in order and in the same cwd, each only if the previous command exited successfully."},
    "cwd": {"type": "string", "description": "Existing workspace-relative directory, or . for the root."},
    "timeout_ms": {"type": "integer", "minimum": 1, "description": "Milliseconds each command may run. Defaults to 120000; values below 10000 are raised to 10000."}
  },
  "required": ["argv", "cwd"],
  "additionalProperties": false
}

git_do.raw:
