list_files.raw:
{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "Workspace-relative directory, or . for the root."},
    "offset": {"type": "integer", "minimum": 0, "description": "Zero-based offset into the sorted listing. Defaults to 0."},
    "limit": {"type": "integer", "minimum": 1, "description": "Maximum entries to return. Defaults to as many as fit."}
  },
  "required": ["path"],
  "additionalProperties": false
}

read_file.raw:
{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "Workspace-relative UTF-8 text file."},
    "start_line": {"type": "integer", "minimum": 1, "description": "One-based first line to read. Defaults to 1."},
    "max_lines": {"type": "integer", "minimum": 1, "description": "Maximum lines to return. Defaults to 250."}
  },
  "required": ["path"],
  "additionalProperties": false
}

report_friction.raw:
{
  "type": "object",
  "properties": {
    "category": {"type": "string", "enum": ["misleading_error", "missing_capability", "unclear_description", "harness_bug", "other"], "description": "Kind of rough edge in the harness."},
    "summary": {"type": "string", "minLength": 1, "maxLength": 300, "description": "One nonblank line describing what happened, at most 300 Unicode characters."},
    "details": {"type": "string", "maxLength": 4000, "description": "Optional explanation, at most 4000 Unicode characters."},
    "related_call_ids": {"type": "array", "items": {"type": "string"}, "maxItems": 20, "description": "Optional IDs of up to 20 calls involved; their existence is not checked."}
  },
  "required": ["category", "summary"],
  "additionalProperties": false
}

search_text.raw:
{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "One workspace-relative file or directory, or . for the root; use exactly one of path or paths."},
    "paths": {"type": "array", "minItems": 1, "maxItems": 20, "items": {"type": "string"}, "description": "Up to 20 workspace-relative files or directories, searched in order; use exactly one of path or paths."},
    "query": {"type": "string", "description": "Single-line query: a literal string, or a pattern when regex is true."},
    "regex": {"type": "boolean", "description": "Treat query as a regular expression. Defaults to false."},
    "max_results": {"type": "integer", "minimum": 1, "description": "Maximum matching lines. Defaults to as many as fit."}
  },
  "required": ["query"],
  "additionalProperties": false
}

write_file.raw:
{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "Workspace-relative UTF-8 text file to create or replace."},
    "content": {"type": "string", "description": "Complete new UTF-8 text for the file."},
    "expected_sha256": {"type": "string", "description": "Optional. Omit it to use the version you last read or wrote; pass a digest only to name a specific version."}
  },
  "required": ["path", "content"],
  "additionalProperties": false
}
